'use client'

import { useState, useMemo } from 'react'
import { Button } from '@/components/ui/button'
import { Card, CardContent } from '@/components/ui/card'
import { Input } from '@/components/ui/input'
import {
  Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle, DialogTrigger
} from '@/components/ui/dialog'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select'
import { Plus, Flame, Check, Trash2 } from 'lucide-react'
import { useHabitStore } from '@/store/useHabitStore'
import type { HabitFrequency } from '@/types/local'
import { format, subDays, isSameDay, parseISO } from 'date-fns'

const HABIT_COLORS = ['#10B981', '#3B82F6', '#8B5CF6', '#EC4899', '#F59E0B', '#EF4444', '#14B8A6']
const FREQ_LABELS: Record<HabitFrequency, string> = { daily: 'Daily', weekly: 'Weekly', weekdays: 'Weekdays' }

export default function HabitsPage() {
  const { habits, addHabit, removeHabit, toggleCompletion } = useHabitStore()
  const [isCreateOpen, setIsCreateOpen] = useState(false)
  const [newName, setNewName] = useState('')
  const [newFrequency, setNewFrequency] = useState<HabitFrequency>('daily')
  const [newColor, setNewColor] = useState('#10B981')

  const todayStr = format(new Date(), 'yyyy-MM-dd')
  const last7Days = useMemo(() => Array.from({ length: 7 }, (_, i) => subDays(new Date(), 6 - i)), [])

  const isCompletedOnDate = (habit: typeof habits[0], date: Date): boolean => {
    const dateStr = format(date, 'yyyy-MM-dd')
    return habit.habit_completions?.some(c => {
      const completedDate = c.completedDate || (c as unknown as Record<string, unknown>).completed_date as string
      return completedDate === dateStr
    }) || false
  }

  const handleCreate = () => {
    if (!newName.trim()) return
    addHabit({ name: newName.trim(), frequency: newFrequency, color: newColor })
    setNewName(''); setNewFrequency('daily'); setNewColor('#10B981')
    setIsCreateOpen(false)
  }

  const handleToggle = (habitId: string) => {
    const habit = habits.find(h => h.id === habitId)
    if (!habit) return
    const isCompleted = isCompletedOnDate(habit, new Date())
    toggleCompletion(habitId, todayStr, !isCompleted)
  }

  const activeHabits = habits.filter(h => !h.deletedAt)

  return (
    <div className="flex-1 p-6 md:p-8 max-w-5xl mx-auto w-full space-y-6">
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-4">
        <div>
          <h1 className="text-3xl md:text-4xl font-serif font-bold tracking-tight">Habits</h1>
          <p className="text-muted-foreground font-medium mt-1">{activeHabits.length} habits tracked</p>
        </div>
        <Dialog open={isCreateOpen} onOpenChange={setIsCreateOpen}>
          <DialogTrigger render={<Button className="rounded-xl bg-accent text-white hover:bg-accent/90 font-medium gap-1.5 cursor-pointer" />}>
            <Plus className="w-4 h-4" /> New Habit
          </DialogTrigger>
          <DialogContent className="rounded-2xl">
            <DialogHeader>
              <DialogTitle className="font-serif text-xl">Track a Habit</DialogTitle>
              <DialogDescription>Build consistency with daily habits.</DialogDescription>
            </DialogHeader>
            <div className="space-y-4 py-2">
              <Input placeholder="e.g. Read 30 minutes" value={newName} onChange={e => setNewName(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleCreate()} autoFocus className="rounded-xl" />
              <Select value={newFrequency} onValueChange={v => setNewFrequency(v as HabitFrequency)}>
                <SelectTrigger className="rounded-xl"><SelectValue /></SelectTrigger>
                <SelectContent>
                  {(['daily','weekly','weekdays'] as HabitFrequency[]).map(f => (
                    <SelectItem key={f} value={f}>{FREQ_LABELS[f]}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <div className="space-y-2">
                <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Color</p>
                <div className="flex gap-2">
                  {HABIT_COLORS.map(c => (
                    <button key={c} onClick={() => setNewColor(c)} className={`w-7 h-7 rounded-full border-2 transition-all cursor-pointer ${newColor === c ? 'border-accent scale-110' : 'border-border/40 hover:scale-105'}`} style={{ backgroundColor: c }} />
                  ))}
                </div>
              </div>
            </div>
            <DialogFooter>
              <Button onClick={handleCreate} className="rounded-xl bg-accent text-white hover:bg-accent/90 cursor-pointer">Create Habit</Button>
            </DialogFooter>
          </DialogContent>
        </Dialog>
      </div>

      {activeHabits.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-20 text-center">
          <Flame className="w-12 h-12 text-muted-foreground/30 mb-4" />
          <h3 className="text-lg font-semibold">No habits yet</h3>
          <p className="text-sm text-muted-foreground mb-4">Start tracking habits to build consistency.</p>
          <Button onClick={() => setIsCreateOpen(true)} variant="outline" className="rounded-xl cursor-pointer">
            <Plus className="w-4 h-4 mr-1.5" /> Track a Habit
          </Button>
        </div>
      ) : (
        <div className="space-y-3">
          {activeHabits.map(habit => {
            const isCompletedToday = isCompletedOnDate(habit, new Date())

            return (
              <Card key={habit.id} className={`border-border/40 rounded-2xl transition-all duration-200 ${isCompletedToday ? 'bg-card/80 border-emerald-500/20' : 'bg-card/60'}`}>
                <CardContent className="p-4">
                  <div className="flex items-center gap-4">
                    {/* Check button */}
                    <button
                      onClick={() => handleToggle(habit.id)}
                      className={`shrink-0 w-9 h-9 rounded-xl flex items-center justify-center transition-all cursor-pointer ${
                        isCompletedToday ? 'bg-emerald-500 text-white' : 'border-2 border-border/50 hover:border-accent/50'
                      }`}
                      aria-label={isCompletedToday ? 'Unmark habit' : 'Mark habit done'}
                    >
                      {isCompletedToday && <Check className="w-4 h-4" />}
                    </button>

                    {/* Habit info */}
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2">
                        <div className="w-2 h-2 rounded-full" style={{ backgroundColor: habit.color }} />
                        <p className={`text-sm font-bold ${isCompletedToday ? 'text-muted-foreground' : 'text-foreground'}`}>
                          {habit.name}
                        </p>
                      </div>
                      <div className="flex items-center gap-2 mt-1">
                        <Flame className="w-3 h-3 text-amber-500" />
                        <span className="text-xs font-semibold text-amber-500">{habit.streak} day streak</span>
                        <span className="text-xs text-muted-foreground">· {FREQ_LABELS[habit.frequency]}</span>
                      </div>
                    </div>

                    {/* 7-day history */}
                    <div className="hidden sm:flex items-center gap-1">
                      {last7Days.map((date, i) => {
                        const completed = isCompletedOnDate(habit, date)
                        const isToday = i === 6
                        return (
                          <div key={i} className="flex flex-col items-center gap-1">
                            <span className="text-[10px] text-muted-foreground/60">{format(date, 'EEE').charAt(0)}</span>
                            <div className={`w-6 h-6 rounded-lg flex items-center justify-center transition-all ${
                              completed ? '' : isToday ? 'border border-dashed border-border/60' : 'bg-secondary/30'
                            }`} style={completed ? { backgroundColor: habit.color } : {}}>
                              {completed && <Check className="w-3 h-3 text-white" />}
                            </div>
                          </div>
                        )
                      })}
                    </div>

                    {/* Delete */}
                    <button onClick={() => removeHabit(habit.id)} className="p-1.5 rounded-lg hover:bg-destructive/10 opacity-0 group-hover:opacity-100 transition-opacity cursor-pointer" aria-label="Delete habit">
                      <Trash2 className="w-3.5 h-3.5 text-destructive/70" />
                    </button>
                  </div>
                </CardContent>
              </Card>
            )
          })}
        </div>
      )}
    </div>
  )
}

'use client'

import { useState, useMemo } from 'react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs'
import {
  Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle, DialogTrigger
} from '@/components/ui/dialog'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select'
import { Checkbox } from '@/components/ui/checkbox'
import {
  Plus, Search, CheckCircle2, Circle, Trash2, Edit2,
  Calendar, Flag, ListTodo, LayoutGrid
} from 'lucide-react'
import { useTaskStore } from '@/store/useTaskStore'
import { useProjectStore } from '@/store/useProjectStore'
import type { TaskPriority, TaskStatus } from '@/types/local'
import { format, parseISO, isToday, isPast } from 'date-fns'


const PRIORITY_COLORS: Record<TaskPriority, string> = {
  urgent: '#EF4444',
  high: '#F59E0B',
  medium: '#3B82F6',
  low: '#6B7280',
}

const PRIORITY_LABELS: Record<TaskPriority, string> = {
  urgent: 'Urgent',
  high: 'High',
  medium: 'Medium',
  low: 'Low',
}

export default function TasksPage() {
  const { tasks, addTask, updateTask, removeTask, toggleStatus } = useTaskStore()
  const { projects } = useProjectStore()
  const [search, setSearch] = useState('')
  const [filterPriority, setFilterPriority] = useState<TaskPriority | 'all'>('all')
  const [filterStatus, setFilterStatus] = useState<TaskStatus | 'all'>('all')
  const [sortBy, setSortBy] = useState<'newest' | 'priority' | 'dueDate'>('newest')
  const [isCreateOpen, setIsCreateOpen] = useState(false)
  const [editingTask, setEditingTask] = useState<string | null>(null)

  // Create form state
  const [newTitle, setNewTitle] = useState('')
  const [newDescription, setNewDescription] = useState('')
  const [newPriority, setNewPriority] = useState<TaskPriority>('medium')
  const [newDueDate, setNewDueDate] = useState('')
  const [newProjectId, setNewProjectId] = useState<string>('')

  // Edit form state
  const [editTitle, setEditTitle] = useState('')
  const [editDescription, setEditDescription] = useState('')
  const [editPriority, setEditPriority] = useState<TaskPriority>('medium')
  const [editDueDate, setEditDueDate] = useState('')

  const activeTasks = tasks.filter(t => !t.deletedAt)

  const filteredTasks = useMemo(() => {
    let result = activeTasks

    if (search) {
      const q = search.toLowerCase()
      result = result.filter(t => t.title.toLowerCase().includes(q) || t.description?.toLowerCase().includes(q))
    }
    if (filterPriority !== 'all') result = result.filter(t => t.priority === filterPriority)
    if (filterStatus !== 'all') result = result.filter(t => t.status === filterStatus)

    result.sort((a, b) => {
      if (sortBy === 'priority') {
        const order: Record<string, number> = { urgent: 0, high: 1, medium: 2, low: 3 }
        return (order[a.priority] ?? 2) - (order[b.priority] ?? 2)
      }
      if (sortBy === 'dueDate') {
        const ad = a.dueDate || (a as unknown as Record<string, unknown>).due_date as string || '9999'
        const bd = b.dueDate || (b as unknown as Record<string, unknown>).due_date as string || '9999'
        return ad.localeCompare(bd)
      }
      return (b.createdAt || (b as unknown as Record<string, unknown>).created_at as string || '').localeCompare(a.createdAt || (a as unknown as Record<string, unknown>).created_at as string || '')
    })

    return result
  }, [activeTasks, search, filterPriority, filterStatus, sortBy])

  const handleCreate = () => {
    if (!newTitle.trim()) return
    addTask({
      title: newTitle.trim(),
      description: newDescription.trim() || null,
      priority: newPriority,
      dueDate: newDueDate || null,
      projectId: newProjectId || null,
    })
    setNewTitle('')
    setNewDescription('')
    setNewPriority('medium')
    setNewDueDate('')
    setNewProjectId('')
    setIsCreateOpen(false)
  }

  const startEdit = (taskId: string) => {
    const task = tasks.find(t => t.id === taskId)
    if (!task) return
    setEditTitle(task.title)
    setEditDescription(task.description || '')
    setEditPriority(task.priority)
    setEditDueDate(task.dueDate || (task as unknown as Record<string, unknown>).due_date as string || '')
    setEditingTask(taskId)
  }

  const handleUpdate = () => {
    if (!editingTask || !editTitle.trim()) return
    updateTask(editingTask, {
      title: editTitle.trim(),
      description: editDescription.trim() || null,
      priority: editPriority,
      dueDate: editDueDate || null,
    })
    setEditingTask(null)
  }

  const todoCount = activeTasks.filter(t => t.status === 'todo').length
  const doneCount = activeTasks.filter(t => t.status === 'done').length

  return (
    <div className="flex-1 p-6 md:p-8 max-w-7xl mx-auto w-full space-y-6">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-4">
        <div>
          <h1 className="text-3xl md:text-4xl font-serif font-bold tracking-tight">Tasks</h1>
          <p className="text-muted-foreground font-medium mt-1">
            {todoCount} to do · {doneCount} completed
          </p>
        </div>
        <Dialog open={isCreateOpen} onOpenChange={setIsCreateOpen}>
          <DialogTrigger render={<Button className="rounded-xl bg-accent text-white hover:bg-accent/90 font-medium gap-1.5 cursor-pointer transition-all" />}>
            <Plus className="w-4 h-4" />
            New Task
          </DialogTrigger>
          <DialogContent className="rounded-2xl">
            <DialogHeader>
              <DialogTitle className="font-serif text-xl">Create Task</DialogTitle>
              <DialogDescription>Add a new task to your workspace.</DialogDescription>
            </DialogHeader>
            <div className="space-y-4 py-2">
              <Input placeholder="Task title" value={newTitle} onChange={e => setNewTitle(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleCreate()} autoFocus className="rounded-xl" />
              <Input placeholder="Description (optional)" value={newDescription} onChange={e => setNewDescription(e.target.value)} className="rounded-xl" />
              <div className="grid grid-cols-2 gap-3">
                <Select value={newPriority} onValueChange={v => setNewPriority(v as TaskPriority)}>
                  <SelectTrigger className="rounded-xl"><SelectValue placeholder="Priority" /></SelectTrigger>
                  <SelectContent>
                    {(['low','medium','high','urgent'] as TaskPriority[]).map(p => (
                      <SelectItem key={p} value={p}>{PRIORITY_LABELS[p]}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                <Input type="date" value={newDueDate} onChange={e => setNewDueDate(e.target.value)} className="rounded-xl" />
              </div>
              {projects.length > 0 && (
                <Select value={newProjectId} onValueChange={(v) => setNewProjectId(v || '')}>
                  <SelectTrigger className="rounded-xl"><SelectValue placeholder="Project (optional)" /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="none">No project</SelectItem>
                    {projects.map(p => (
                      <SelectItem key={p.id} value={p.id}>{p.name}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              )}
            </div>
            <DialogFooter>
              <Button onClick={handleCreate} className="rounded-xl bg-accent text-white hover:bg-accent/90 cursor-pointer">Create Task</Button>
            </DialogFooter>
          </DialogContent>
        </Dialog>
      </div>

      {/* Filters */}
      <div className="flex flex-wrap items-center gap-2">
        <div className="relative flex-1 min-w-[200px] max-w-sm">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input placeholder="Search tasks..." value={search} onChange={e => setSearch(e.target.value)} className="pl-9 rounded-xl border-border/50 bg-card/60" />
        </div>
        <Select value={filterPriority} onValueChange={v => setFilterPriority(v as TaskPriority | 'all')}>
          <SelectTrigger className="w-[130px] rounded-xl border-border/50"><SelectValue /></SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Priority</SelectItem>
            {(['urgent','high','medium','low'] as TaskPriority[]).map(p => (
              <SelectItem key={p} value={p}>{PRIORITY_LABELS[p]}</SelectItem>
            ))}
          </SelectContent>
        </Select>
        <Select value={filterStatus} onValueChange={v => setFilterStatus(v as TaskStatus | 'all')}>
          <SelectTrigger className="w-[130px] rounded-xl border-border/50"><SelectValue /></SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Status</SelectItem>
            <SelectItem value="todo">To Do</SelectItem>
            <SelectItem value="in_progress">In Progress</SelectItem>
            <SelectItem value="done">Done</SelectItem>
          </SelectContent>
        </Select>
        <Select value={sortBy} onValueChange={v => setSortBy(v as 'newest' | 'priority' | 'dueDate')}>
          <SelectTrigger className="w-[130px] rounded-xl border-border/50"><SelectValue /></SelectTrigger>
          <SelectContent>
            <SelectItem value="newest">Newest</SelectItem>
            <SelectItem value="priority">Priority</SelectItem>
            <SelectItem value="dueDate">Due Date</SelectItem>
          </SelectContent>
        </Select>
      </div>

      {/* Task List */}
      {filteredTasks.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-20 text-center">
          <ListTodo className="w-12 h-12 text-muted-foreground/30 mb-4" />
          <h3 className="text-lg font-semibold text-foreground mb-1">No tasks yet</h3>
          <p className="text-sm text-muted-foreground mb-4">Create your first task to get started.</p>
          <Button onClick={() => setIsCreateOpen(true)} variant="outline" className="rounded-xl cursor-pointer">
            <Plus className="w-4 h-4 mr-1.5" />
            Create Task
          </Button>
        </div>
      ) : (
        <div className="space-y-2">
          {filteredTasks.map((task) => {
            const dueDate = task.dueDate || (task as unknown as Record<string, unknown>).due_date as string
            const isOverdue = dueDate && task.status !== 'done' && isPast(parseISO(dueDate)) && !isToday(parseISO(dueDate))

            return (
              <div
                key={task.id}
                className={`group flex items-center gap-3 p-3.5 rounded-xl border transition-all duration-200 cursor-pointer ${
                  task.status === 'done'
                    ? 'bg-card/30 border-border/30 opacity-60'
                    : 'bg-card/60 border-border/40 hover:border-border/60 hover:bg-card/80'
                }`}
              >
                {/* Toggle */}
                <button onClick={() => toggleStatus(task.id)} className="shrink-0 cursor-pointer" aria-label={task.status === 'done' ? 'Mark incomplete' : 'Mark complete'}>
                  {task.status === 'done' ? (
                    <CheckCircle2 className="w-5 h-5 text-emerald-500" />
                  ) : (
                    <Circle className="w-5 h-5 text-muted-foreground/40 group-hover:text-muted-foreground transition-colors" />
                  )}
                </button>

                {/* Content */}
                <div className="flex-1 min-w-0">
                  <p className={`text-sm font-semibold truncate ${task.status === 'done' ? 'line-through text-muted-foreground' : 'text-foreground'}`}>
                    {task.title}
                  </p>
                  {task.description && (
                    <p className="text-xs text-muted-foreground truncate mt-0.5">{task.description}</p>
                  )}
                </div>

                {/* Meta */}
                <div className="flex items-center gap-2 shrink-0">
                  {dueDate && (
                    <span className={`text-xs font-medium flex items-center gap-1 ${isOverdue ? 'text-destructive' : 'text-muted-foreground'}`}>
                      <Calendar className="w-3 h-3" />
                      {format(parseISO(dueDate), 'MMM d')}
                    </span>
                  )}
                  <div className="flex items-center gap-1" title={PRIORITY_LABELS[task.priority]}>
                    <Flag className="w-3 h-3" style={{ color: PRIORITY_COLORS[task.priority] }} />
                  </div>
                  <button onClick={() => startEdit(task.id)} className="opacity-0 group-hover:opacity-100 transition-opacity cursor-pointer p-1 rounded hover:bg-secondary/40" aria-label="Edit task">
                    <Edit2 className="w-3.5 h-3.5 text-muted-foreground" />
                  </button>
                  <button onClick={() => removeTask(task.id)} className="opacity-0 group-hover:opacity-100 transition-opacity cursor-pointer p-1 rounded hover:bg-destructive/10" aria-label="Delete task">
                    <Trash2 className="w-3.5 h-3.5 text-destructive/70" />
                  </button>
                </div>
              </div>
            )
          })}
        </div>
      )}

      {/* Edit Dialog */}
      <Dialog open={!!editingTask} onOpenChange={(open) => !open && setEditingTask(null)}>
        <DialogContent className="rounded-2xl">
          <DialogHeader>
            <DialogTitle className="font-serif text-xl">Edit Task</DialogTitle>
          </DialogHeader>
          <div className="space-y-4 py-2">
            <Input value={editTitle} onChange={e => setEditTitle(e.target.value)} className="rounded-xl" autoFocus />
            <Input value={editDescription} onChange={e => setEditDescription(e.target.value)} placeholder="Description" className="rounded-xl" />
            <div className="grid grid-cols-2 gap-3">
              <Select value={editPriority} onValueChange={v => setEditPriority(v as TaskPriority)}>
                <SelectTrigger className="rounded-xl"><SelectValue /></SelectTrigger>
                <SelectContent>
                  {(['low','medium','high','urgent'] as TaskPriority[]).map(p => (
                    <SelectItem key={p} value={p}>{PRIORITY_LABELS[p]}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <Input type="date" value={editDueDate} onChange={e => setEditDueDate(e.target.value)} className="rounded-xl" />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setEditingTask(null)} className="rounded-xl cursor-pointer">Cancel</Button>
            <Button onClick={handleUpdate} className="rounded-xl bg-accent text-white hover:bg-accent/90 cursor-pointer">Save Changes</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import { z } from 'zod'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { useAppStore } from '@/store/appStore'
import { useAgentStore } from '@/store/agentStore'
import { useCharacterStore, CHARACTER_HAIR, CHARACTER_OUTFITS, OUTFIT_COLORS } from '@/store/characterStore'
import { CompanionAvatar } from '@/features/companion/CompanionAvatar'
import { ArrowRight, Sparkles, User, Bot, Palette, ChevronLeft } from 'lucide-react'

const nameSchema = z.string().trim().min(1, 'Please enter your name.').max(50)
const agentNameSchema = z.string().trim().min(1, 'Give your companion a name.').max(30)

type OnboardingStep = 'welcome' | 'name' | 'agent' | 'appearance' | 'ready'

export default function Home() {
  const router = useRouter()
  const { preferences, setDisplayName, setAgentName, completeOnboarding } = useAppStore()
  const { setName: setAgentStoreName } = useAgentStore()
  const characterConfig = useCharacterStore((s) => s.config)
  const setHair = useCharacterStore((s) => s.setHair)
  const setOutfit = useCharacterStore((s) => s.setOutfit)

  const [step, setStep] = useState<OnboardingStep>('welcome')
  const [name, setName] = useState('')
  const [agentName, setAgentNameValue] = useState('Nexora')
  const [nameError, setNameError] = useState('')
  const [agentError, setAgentError] = useState('')
  const [isLoading, setIsLoading] = useState(true)

  useEffect(() => {
    if (preferences.onboardingComplete && preferences.displayName) {
      router.push('/dashboard')
    } else {
      setIsLoading(false)
    }
  }, [preferences.onboardingComplete, preferences.displayName, router])

  const handleNameSubmit = () => {
    const parsed = nameSchema.safeParse(name)
    if (!parsed.success) {
      setNameError(parsed.error.issues[0]?.message || 'Invalid name')
      return
    }
    setDisplayName(parsed.data)
    // Migrate old localStorage name
    localStorage.setItem('nexora_guest_name', parsed.data)
    setStep('agent')
  }

  const handleAgentSubmit = () => {
    const parsed = agentNameSchema.safeParse(agentName)
    if (!parsed.success) {
      setAgentError(parsed.error.issues[0]?.message || 'Invalid name')
      return
    }
    setAgentName(parsed.data)
    setAgentStoreName(parsed.data)
    setStep('appearance')
  }

  const handleComplete = () => {
    completeOnboarding()
    router.push('/dashboard')
  }

  const handleSkipToApp = () => {
    if (name.trim()) {
      setDisplayName(name.trim())
      localStorage.setItem('nexora_guest_name', name.trim())
    } else {
      setDisplayName('Explorer')
      localStorage.setItem('nexora_guest_name', 'Explorer')
    }
    setAgentName(agentName || 'Nexora')
    setAgentStoreName(agentName || 'Nexora')
    completeOnboarding()
    router.push('/dashboard')
  }

  if (isLoading) {
    return <div className="min-h-screen bg-background" />
  }

  return (
    <div className="min-h-screen bg-background text-foreground flex flex-col items-center justify-center p-4 selection:bg-accent/20">
      {/* Background gradient */}
      <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_top,_var(--tw-gradient-stops))] from-accent/5 via-background to-background" />

      <main className="relative z-10 w-full max-w-lg mx-auto flex flex-col items-center text-center">
        {/* Step: Welcome */}
        {step === 'welcome' && (
          <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-500">
            <div className="inline-flex items-center space-x-2 px-3 py-1.5 rounded-full bg-accent/10 border border-accent/20">
              <Sparkles className="w-3.5 h-3.5 text-accent" />
              <span className="text-xs font-semibold text-accent uppercase tracking-wider">Nexora 2.0</span>
            </div>

            <h1 className="text-5xl sm:text-6xl font-serif font-semibold tracking-tight leading-tight">
              Your workspace,<br />
              <span className="text-transparent bg-clip-text bg-gradient-to-r from-foreground/90 to-foreground/40">
                without the friction.
              </span>
            </h1>

            <p className="text-lg text-muted-foreground max-w-md mx-auto font-light leading-relaxed">
              Organize tasks, projects, and goals in one focused workspace.
              No account needed. Start immediately.
            </p>

            <div className="flex flex-col sm:flex-row gap-3 pt-4 justify-center">
              <Button
                onClick={() => setStep('name')}
                className="h-13 px-8 rounded-xl bg-accent text-white hover:bg-accent/90 font-medium text-base transition-all duration-300 shadow-[0_4px_14px_0_var(--accent)/25] hover:-translate-y-0.5 cursor-pointer"
              >
                Get Started
                <ArrowRight className="w-4 h-4 ml-2" />
              </Button>
              <Button
                variant="outline"
                onClick={handleSkipToApp}
                className="h-13 px-8 rounded-xl border-border/60 font-medium text-base hover:bg-secondary/40 transition-all cursor-pointer"
              >
                Skip Setup
              </Button>
            </div>
          </div>
        )}

        {/* Step: Name */}
        {step === 'name' && (
          <div className="w-full space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-500">
            <button onClick={() => setStep('welcome')} className="flex items-center gap-1.5 text-sm text-muted-foreground hover:text-foreground transition-colors cursor-pointer">
              <ChevronLeft className="w-4 h-4" />
              Back
            </button>
            <div className="flex items-center justify-center w-16 h-16 rounded-2xl bg-accent/10 border border-accent/20 mx-auto">
              <User className="w-7 h-7 text-accent" />
            </div>
            <div className="space-y-2">
              <h2 className="text-3xl font-serif font-bold tracking-tight">What should we call you?</h2>
              <p className="text-muted-foreground">Your display name in Nexora.</p>
            </div>
            <div className="space-y-4">
              <Input
                placeholder="Enter your name"
                value={name}
                onChange={(e) => { setName(e.target.value); setNameError('') }}
                onKeyDown={(e) => e.key === 'Enter' && handleNameSubmit()}
                className="h-14 px-5 text-lg bg-card border-border/60 rounded-xl text-center placeholder:text-muted-foreground/50 transition-all hover:border-accent/40 focus-visible:ring-accent/30"
                autoFocus
              />
              {nameError && <p className="text-sm text-destructive font-medium">{nameError}</p>}
              <Button onClick={handleNameSubmit} className="w-full h-13 rounded-xl bg-accent text-white hover:bg-accent/90 font-medium text-base transition-all cursor-pointer">
                Continue
                <ArrowRight className="w-4 h-4 ml-2" />
              </Button>
            </div>
          </div>
        )}

        {/* Step: Agent */}
        {step === 'agent' && (
          <div className="w-full space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-500">
            <button onClick={() => setStep('name')} className="flex items-center gap-1.5 text-sm text-muted-foreground hover:text-foreground transition-colors cursor-pointer">
              <ChevronLeft className="w-4 h-4" />
              Back
            </button>
            <div className="flex items-center justify-center w-16 h-16 rounded-2xl bg-accent/10 border border-accent/20 mx-auto">
              <Bot className="w-7 h-7 text-accent" />
            </div>
            <div className="space-y-2">
              <h2 className="text-3xl font-serif font-bold tracking-tight">Meet your companion.</h2>
              <p className="text-muted-foreground">Give your productivity companion a name.</p>
            </div>
            <div className="space-y-3">
              <Input
                placeholder="e.g. Nexora, Nova, Atlas, Astra"
                value={agentName}
                onChange={(e) => { setAgentNameValue(e.target.value); setAgentError('') }}
                onKeyDown={(e) => e.key === 'Enter' && handleAgentSubmit()}
                className="h-14 px-5 text-lg bg-card border-border/60 rounded-xl text-center placeholder:text-muted-foreground/50 transition-all hover:border-accent/40 focus-visible:ring-accent/30"
                autoFocus
              />
              <div className="flex flex-wrap gap-2 justify-center">
                {['Nexora', 'Nova', 'Atlas', 'Astra', 'Kyro', 'Orion'].map((suggestion) => (
                  <button
                    key={suggestion}
                    onClick={() => setAgentNameValue(suggestion)}
                    className={`px-3 py-1.5 rounded-lg text-sm font-medium border transition-all cursor-pointer ${
                      agentName === suggestion
                        ? 'bg-accent/10 border-accent/30 text-accent'
                        : 'border-border/50 text-muted-foreground hover:text-foreground hover:border-border'
                    }`}
                  >
                    {suggestion}
                  </button>
                ))}
              </div>
              {agentError && <p className="text-sm text-destructive font-medium">{agentError}</p>}
              <Button onClick={handleAgentSubmit} className="w-full h-13 rounded-xl bg-accent text-white hover:bg-accent/90 font-medium text-base transition-all cursor-pointer">
                Continue
                <ArrowRight className="w-4 h-4 ml-2" />
              </Button>
            </div>
          </div>
        )}

        {/* Step: Appearance */}
        {step === 'appearance' && (
          <div className="w-full space-y-6 animate-in fade-in slide-in-from-bottom-6 duration-500">
            <button onClick={() => setStep('agent')} className="flex items-center gap-1.5 text-sm text-muted-foreground hover:text-foreground transition-colors cursor-pointer">
              <ChevronLeft className="w-4 h-4" />
              Back
            </button>
            <div className="flex items-center justify-center w-16 h-16 rounded-2xl bg-accent/10 border border-accent/20 mx-auto">
              <Palette className="w-7 h-7 text-accent" />
            </div>
            <div className="space-y-2">
              <h2 className="text-3xl font-serif font-bold tracking-tight">Make it yours.</h2>
              <p className="text-muted-foreground">Customize your companion&apos;s look.</p>
            </div>

            {/* Live Preview */}
            <div className="flex justify-center py-4">
              <div className="relative p-4 rounded-2xl bg-card border border-border/40">
                <CompanionAvatar size={140} expression="happy" />
                <p className="text-center text-sm font-medium text-muted-foreground mt-2">{agentName}</p>
              </div>
            </div>

            {/* Quick Customization */}
            <div className="space-y-4">
              <div>
                <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-2">Hair Style</p>
                <div className="flex flex-wrap gap-2 justify-center">
                  {CHARACTER_HAIR.slice(0, 4).map((h) => (
                    <button
                      key={h.id}
                      onClick={() => setHair(h.id)}
                      className={`px-3 py-1.5 rounded-lg text-sm font-medium border transition-all cursor-pointer ${
                        characterConfig.hair === h.id
                          ? 'bg-accent/10 border-accent/30 text-accent'
                          : 'border-border/50 text-muted-foreground hover:border-border'
                      }`}
                    >
                      {h.label}
                    </button>
                  ))}
                </div>
              </div>
              <div>
                <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-2">Outfit</p>
                <div className="flex flex-wrap gap-2 justify-center">
                  {CHARACTER_OUTFITS.map((o) => (
                    <button
                      key={o.id}
                      onClick={() => setOutfit(o.id)}
                      className={`px-3 py-1.5 rounded-lg text-sm font-medium border transition-all cursor-pointer ${
                        characterConfig.outfit === o.id
                          ? 'bg-accent/10 border-accent/30 text-accent'
                          : 'border-border/50 text-muted-foreground hover:border-border'
                      }`}
                    >
                      {o.label}
                    </button>
                  ))}
                </div>
              </div>
              <div>
                <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-2">Color</p>
                <div className="flex flex-wrap gap-2 justify-center">
                  {OUTFIT_COLORS.slice(0, 6).map((c) => (
                    <button
                      key={c}
                      onClick={() => setOutfit(characterConfig.outfit, c)}
                      className={`w-8 h-8 rounded-full border-2 transition-all cursor-pointer ${
                        characterConfig.outfitColor === c ? 'border-accent scale-110' : 'border-border/40 hover:scale-105'
                      }`}
                      style={{ backgroundColor: c }}
                      aria-label={`Outfit color ${c}`}
                    />
                  ))}
                </div>
              </div>
            </div>

            <Button onClick={() => setStep('ready')} className="w-full h-13 rounded-xl bg-accent text-white hover:bg-accent/90 font-medium text-base transition-all cursor-pointer">
              Continue
              <ArrowRight className="w-4 h-4 ml-2" />
            </Button>
          </div>
        )}

        {/* Step: Ready */}
        {step === 'ready' && (
          <div className="w-full space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-500">
            <div className="flex justify-center">
              <CompanionAvatar size={100} expression="celebrating" />
            </div>
            <div className="space-y-3">
              <h2 className="text-4xl font-serif font-bold tracking-tight">You&apos;re all set, {name}.</h2>
              <p className="text-muted-foreground text-lg">
                {agentName} is ready to help you stay focused and productive. No account needed — your data is saved right here.
              </p>
            </div>
            <Button
              onClick={handleComplete}
              className="w-full h-14 rounded-xl bg-accent text-white hover:bg-accent/90 font-medium text-lg transition-all shadow-[0_4px_14px_0_var(--accent)/25] hover:-translate-y-0.5 cursor-pointer"
            >
              Enter Nexora
              <Sparkles className="w-4 h-4 ml-2" />
            </Button>
          </div>
        )}

        {/* Step indicators */}
        {step !== 'welcome' && (
          <div className="flex gap-1.5 mt-8">
            {['name', 'agent', 'appearance', 'ready'].map((s, i) => (
              <div
                key={s}
                className={`h-1.5 rounded-full transition-all duration-300 ${
                  ['name', 'agent', 'appearance', 'ready'].indexOf(step) >= i
                    ? 'bg-accent w-6'
                    : 'bg-border w-3'
                }`}
              />
            ))}
          </div>
        )}
      </main>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import Link from 'next/link'
import { logout } from '@/features/auth/actions'

export function HeaderUserProfile({ userEmail }: { userEmail?: string }) {
  const [guestName, setGuestName] = useState<string | null>(null)

  useEffect(() => {
    if (!userEmail) {
      setGuestName(localStorage.getItem('nexora_guest_name'))
    }
  }, [userEmail])

  if (userEmail) {
    return (
      <div className="flex items-center gap-3 border-l border-border pl-6">
        <span className="text-sm font-medium text-muted-foreground hidden md:inline-block">
          {userEmail}
        </span>
        <form action={logout}>
          <button
            type="submit"
            className="rounded-full border border-border bg-secondary px-4 py-1.5 text-sm font-medium text-foreground shadow-sm hover:bg-secondary/80 transition-colors focus:outline-none focus:ring-2 focus:ring-primary focus:ring-offset-2 focus:ring-offset-background"
          >
            Sign out
          </button>
        </form>
      </div>
    )
  }

  return (
    <div className="flex items-center gap-3 border-l border-border pl-6">
      {guestName && (
        <span className="text-sm font-medium text-muted-foreground hidden md:inline-block">
          {guestName} (Guest)
        </span>
      )}
      <Link href="/login" className="rounded-full border border-border bg-primary px-4 py-1.5 text-sm font-medium text-primary-foreground shadow-sm hover:bg-primary/90 transition-colors focus:outline-none focus:ring-2 focus:ring-primary focus:ring-offset-2 focus:ring-offset-background">
        Save / Sign in
      </Link>
    </div>
  )
}

