'use client'

import { createContext, useContext, useEffect, useState } from 'react'
import { User } from '@supabase/supabase-js'
import { createClient } from '@/lib/supabase/client'

interface AuthContextType {
  user: User | null
  isLoading: boolean
}

const AuthContext = createContext<AuthContextType>({
  user: null,
  isLoading: true,
})

export function AuthProvider({ children, initialUser }: { children: React.ReactNode, initialUser: User | null }) {
  const [user, setUser] = useState<User | null>(initialUser)
  const [isLoading, setIsLoading] = useState(!initialUser)
  const supabase = createClient()

  useEffect(() => {
    if (initialUser) {
      setIsLoading(false)
      return
    }

    const { data: { subscription } } = supabase.auth.onAuthStateChange(
      (event, session) => {
        setUser(session?.user || null)
        setIsLoading(false)
      }
    )

    // Initial fetch in case onAuthStateChange doesn't fire immediately
    supabase.auth.getUser().then(({ data }) => {
      setUser(data.user)
      setIsLoading(false)
    })

    return () => {
      subscription.unsubscribe()
    }
  }, [initialUser, supabase])

  return (
    <AuthContext.Provider value={{ user, isLoading }}>
      {children}
    </AuthContext.Provider>
  )
}

export function useAuth() {
  return useContext(AuthContext)
}

'use client'

import { create } from 'zustand'
import { persist } from 'zustand/middleware'
import type { AppMode, LocalPreferences, DEFAULT_PREFERENCES } from '@/types/local'
import { useAuth } from '@/providers/AuthProvider'

interface AppModeState {
  mode: AppMode
  preferences: LocalPreferences
  setMode: (mode: AppMode) => void
  setPreferences: (prefs: Partial<LocalPreferences>) => void
  setDisplayName: (name: string) => void
  setAgentName: (name: string) => void
  completeOnboarding: () => void
  resetPreferences: () => void
}

const defaultPrefs: LocalPreferences = {
  displayName: '',
  theme: 'dark',
  accentColor: '#6366F1',
  onboardingComplete: false,
  agentName: 'Nexora',
  sidebarCollapsed: false,
  language: 'en',
  pomodoroDuration: 25,
  shortBreakDuration: 5,
  longBreakDuration: 15,
}

export const useAppStore = create<AppModeState>()(
  persist(
    (set) => ({
      mode: 'guest',
      preferences: defaultPrefs,
      setMode: (mode) => set({ mode }),
      setPreferences: (prefs) =>
        set((state) => ({
          preferences: { ...state.preferences, ...prefs },
        })),
      setDisplayName: (name) =>
        set((state) => ({
          preferences: { ...state.preferences, displayName: name },
        })),
      setAgentName: (name) =>
        set((state) => ({
          preferences: { ...state.preferences, agentName: name },
        })),
      completeOnboarding: () =>
        set((state) => ({
          preferences: { ...state.preferences, onboardingComplete: true },
        })),
      resetPreferences: () => set({ preferences: defaultPrefs, mode: 'guest' }),
    }),
    {
      name: 'nexora_app_state',
      partialize: (state) => ({
        preferences: state.preferences,
      }),
    }
  )
)

/** Hook that derives app mode from both store and auth state */
export function useAppMode() {
  const { user, isLoading: authLoading } = useAuth()
  const storeMode = useAppStore((s) => s.mode)
  const setMode = useAppStore((s) => s.setMode)

  const effectiveMode: AppMode = user
    ? storeMode === 'syncing'
      ? 'syncing'
      : 'authenticated'
    : navigator.onLine
    ? 'guest'
    : 'offline'

  return {
    mode: effectiveMode,
    isGuest: !user,
    isAuthenticated: !!user,
    isLoading: authLoading,
    setMode,
    user,
  }
}

import { create } from 'zustand'
import { persist } from 'zustand/middleware'
import type { LocalHabit, LocalHabitCompletion } from '@/types/local'
import { createLocalHabit, createLocalId, nowISO } from '@/types/local'
import { dbGetAll, dbPut, dbDelete } from '@/lib/db/indexeddb'

export type Habit = LocalHabit & {
  habit_completions?: LocalHabitCompletion[]
}

interface HabitStore {
  habits: Habit[]
  setHabits: (habits: Habit[]) => void
  addHabit: (partial: Partial<LocalHabit> & { name: string }) => Habit
  updateHabit: (id: string, updates: Partial<Habit>) => void
  removeHabit: (id: string) => void
  toggleCompletion: (habitId: string, date: string, isCompleted: boolean, updatedStreak?: number) => void
  hydrate: () => Promise<void>
}

export const useHabitStore = create<HabitStore>()(
  persist(
    (set, get) => ({
      habits: [],
      setHabits: (habits) => set({ habits }),
      addHabit: (partial) => {
        const habit: Habit = { ...createLocalHabit(partial), habit_completions: [] }
        set((state) => ({ habits: [...state.habits, habit] }))
        dbPut('habits', habit).catch(console.error)
        return habit
      },
      updateHabit: (id, updates) =>
        set((state) => {
          const habits = state.habits.map((h) => (h.id === id ? { ...h, ...updates, updatedAt: nowISO() } : h))
          const updated = habits.find((h) => h.id === id)
          if (updated) dbPut('habits', updated).catch(console.error)
          return { habits }
        }),
      removeHabit: (id) => {
        set((state) => ({ habits: state.habits.filter((h) => h.id !== id) }))
        dbDelete('habits', id).catch(console.error)
      },
      toggleCompletion: (habitId, date, isCompleted, updatedStreak) =>
        set((state) => {
          const habits = state.habits.map((habit) => {
            if (habit.id === habitId) {
              const completions = habit.habit_completions || []
              if (isCompleted) {
                const newCompletion: LocalHabitCompletion = {
                  id: createLocalId(),
                  habitId,
                  completedDate: date,
                  createdAt: nowISO(),
                }
                const updated = {
                  ...habit,
                  habit_completions: [...completions, newCompletion],
                  streak: typeof updatedStreak === 'number' ? updatedStreak : habit.streak + 1,
                  updatedAt: nowISO(),
                }
                dbPut('habits', updated).catch(console.error)
                return updated
              } else {
                const updated = {
                  ...habit,
                  habit_completions: completions.filter((c) => c.completedDate !== date),
                  streak: typeof updatedStreak === 'number' ? updatedStreak : Math.max(0, habit.streak - 1),
                  updatedAt: nowISO(),
                }
                dbPut('habits', updated).catch(console.error)
                return updated
              }
            }
            return habit
          })
          return { habits }
        }),
      hydrate: async () => {
        try {
          const habits = await dbGetAll<Habit>('habits')
          if (habits.length > 0) {
            set({ habits })
          }
        } catch {
          // Keep existing state
        }
      },
    }),
    {
      name: 'nexora_guest_habits',
      partialize: (state) => ({ habits: state.habits }),
    }
  )
)

import { create } from 'zustand'
import { persist } from 'zustand/middleware'
import type { LocalTask, TaskPriority, TaskStatus } from '@/types/local'
import { createLocalTask, nowISO } from '@/types/local'
import { dbGetAll, dbPut, dbDelete } from '@/lib/db/indexeddb'

interface TaskState {
  tasks: LocalTask[]
  isLoading: boolean
  isHydrated: boolean
  setTasks: (tasks: LocalTask[]) => void
  addTask: (partial: Partial<LocalTask> & { title: string }) => LocalTask
  updateTask: (id: string, updates: Partial<LocalTask>) => void
  removeTask: (id: string) => void
  toggleStatus: (id: string) => void
  hydrate: () => Promise<void>
}

export const useTaskStore = create<TaskState>()(
  persist(
    (set, get) => ({
      tasks: [],
      isLoading: true,
      isHydrated: false,
      setTasks: (tasks) => set({ tasks, isLoading: false }),
      addTask: (partial) => {
        const task = createLocalTask(partial)
        set((state) => ({ tasks: [task, ...state.tasks] }))
        // Async persist to IndexedDB
        dbPut('tasks', task).catch(console.error)
        return task
      },
      updateTask: (id, updates) => {
        const updatedAt = nowISO()
        set((state) => ({
          tasks: state.tasks.map((t) =>
            t.id === id ? { ...t, ...updates, updatedAt } : t
          ),
        }))
        // Async persist
        const task = get().tasks.find((t) => t.id === id)
        if (task) dbPut('tasks', task).catch(console.error)
      },
      removeTask: (id) => {
        set((state) => ({
          tasks: state.tasks.filter((t) => t.id !== id),
        }))
        dbDelete('tasks', id).catch(console.error)
      },
      toggleStatus: (id) => {
        const updatedAt = nowISO()
        set((state) => ({
          tasks: state.tasks.map((t) => {
            if (t.id === id) {
              const newStatus: TaskStatus = t.status === 'done' ? 'todo' : 'done'
              return { ...t, status: newStatus, updatedAt }
            }
            return t
          }),
        }))
        const task = get().tasks.find((t) => t.id === id)
        if (task) dbPut('tasks', task).catch(console.error)
      },
      hydrate: async () => {
        try {
          const tasks = await dbGetAll<LocalTask>('tasks')
          if (tasks.length > 0) {
            set({ tasks, isLoading: false, isHydrated: true })
          } else {
            set({ isLoading: false, isHydrated: true })
          }
        } catch {
          set({ isLoading: false, isHydrated: true })
        }
      },
    }),
    {
      name: 'nexora_guest_tasks',
      partialize: (state) => ({ tasks: state.tasks }),
    }
  )
)
